class Solution {
public:
    vector<int> survivedRobotsHealths(vector<int>& positions, vector<int>& healths, string directions) {
        int n = positions.size();
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b) {
            return positions[a] < positions[b];
        });
        vector<int> stack;
        for (int i : idx) {
            if (directions[i] == 'R') {
                stack.push_back(i);
            } else {
                while (!stack.empty() && healths[i] > 0) {
                    int top = stack.back();
                    if (healths[top] < healths[i]) {
                        healths[i]--;
                        healths[top] = 0;
                        stack.pop_back();
                    } else if (healths[top] > healths[i]) {
                        healths[top]--;
                        healths[i] = 0;
                    } else {
                        healths[top] = 0;
                        healths[i] = 0;
                        stack.pop_back();
                    }
                }
            }
        }
        vector<int> ans;
        for (int i = 0; i < n; ++i) {
            if (healths[i] > 0) ans.push_back(healths[i]);
        }
        return ans;
    }
};

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

class Solution {
    public List<Integer> survivedRobotsHealths(int[] positions, int[] healths, String directions) {
        int n = positions.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Integer.compare(positions[a], positions[b]));
        List<Integer> stack = new ArrayList<>();
        for (int i : idx) {
            if (directions.charAt(i) == 'R') {
                stack.add(i);
            } else {
                while (!stack.isEmpty() && healths[i] > 0) {
                    int top = stack.get(stack.size() - 1);
                    if (healths[top] < healths[i]) {
                        healths[i]--;
                        healths[top] = 0;
                        stack.remove(stack.size() - 1);
                    } else if (healths[top] > healths[i]) {
                        healths[top]--;
                        healths[i] = 0;
                    } else {
                        healths[top] = 0;
                        healths[i] = 0;
                        stack.remove(stack.size() - 1);
                    }
                }
            }
        }
        List<Integer> ans = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (healths[i] > 0) ans.add(healths[i]);
        }
        return ans;
    }
}

var survivedRobotsHealths = function(positions, healths, directions) {
    const n = positions.length;
    const idx = Array.from({ length: n }, (_, i) => i);
    idx.sort((a, b) => positions[a] - positions[b]);
    const stack = [];
    for (const i of idx) {
        if (directions[i] === 'R') {
            stack.push(i);
        } else {
            while (stack.length > 0 && healths[i] > 0) {
                const top = stack[stack.length - 1];
                if (healths[top] < healths[i]) {
                    healths[i]--;
                    healths[top] = 0;
                    stack.pop();
                } else if (healths[top] > healths[i]) {
                    healths[top]--;
                    healths[i] = 0;
                } else {
                    healths[top] = 0;
                    healths[i] = 0;
                    stack.pop();
                }
            }
        }
    }
    const ans = [];
    for (let i = 0; i < n; i++) {
        if (healths[i] > 0) ans.push(healths[i]);
    }
    return ans;
